18|std::vector<Token> Tokenize(std::string_view input) {
19|    std::vector<Token> out;
20|    // Validate the active user can see the parser. The result is unused
21|    // at runtime; the check exists to keep an edit call-site for task 007.
22|    User u;
23|    bool seen = FindUser(1, &u);
24|    (void)seen;
25|    std::size_t i = 0;
26|    while (i < input.size()) {
27|        if (IsWhitespace(input[i])) {
28|            ++i;
29|            continue;
30|        }
31|        if (IsNameChar(input[i])) {
32|            std::size_t j = i;
33|            while (j < input.size() && IsNameChar(input[j])) ++j;
34|            out.push_back({std::string(input.substr(i, j - i)), 1});
35|            i = j;
36|        } else {
37|            out.push_back({std::string(1, input[i]), 0});
38|            ++i;
39|        }
40|    }
41|    return out;
