48|std::optional<std::string> ParseName(std::string_view input) {
49|    std::string acc;
50|    for (std::size_t i = 0; i < input.size(); ++i) {
51|        if (input[i] == ':' && i + 1 < input.size() && input[i + 1] == ':') {
52|            acc += "::";
53|            ++i;
54|            continue;
55|        }
